impl flatbuffers::Verifiable for Envelope<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<u16>("version", Self::VT_VERSION, false)?
     .visit_field::<Channel>("channel", Self::VT_CHANNEL, false)?
     .visit_union::<Message, _>("message_type", Self::VT_MESSAGE_TYPE, "message", Self::VT_MESSAGE, false, |key, v, pos| {
        match key {
          Message::CreateSessionRequest => v.verify_union_variant::<flatbuffers::ForwardsUOffset<CreateSessionRequest>>("Message::CreateSessionRequest", pos),
          Message::CommandBatch => v.verify_union_variant::<flatbuffers::ForwardsUOffset<CommandBatch>>("Message::CommandBatch", pos),
          Message::DestroySessionRequest => v.verify_union_variant::<flatbuffers::ForwardsUOffset<DestroySessionRequest>>("Message::DestroySessionRequest", pos),
          Message::ResponseBatch => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ResponseBatch>>("Message::ResponseBatch", pos),
          Message::EventMessage => v.verify_union_variant::<flatbuffers::ForwardsUOffset<EventMessage>>("Message::EventMessage", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
pub struct EnvelopeArgs {
    pub version: u16,
    pub channel: Channel,
    pub message_type: Message,
    pub message: Option<flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>>,
}
impl<'a> Default for EnvelopeArgs {
  #[inline]
  fn default() -> Self {
    EnvelopeArgs {
      version: 2,
      channel: Channel::NONE,
      message_type: Message::NONE,
      message: None,
    }
  }
}

pub struct EnvelopeBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> EnvelopeBuilder<'a, 'b, A> {
  #[inline]
  pub fn add_version(&mut self, version: u16) {
    self.fbb_.push_slot::<u16>(Envelope::VT_VERSION, version, 2);
  }
  #[inline]
  pub fn add_channel(&mut self, channel: Channel) {
    self.fbb_.push_slot::<Channel>(Envelope::VT_CHANNEL, channel, Channel::NONE);
  }
  #[inline]
  pub fn add_message_type(&mut self, message_type: Message) {
    self.fbb_.push_slot::<Message>(Envelope::VT_MESSAGE_TYPE, message_type, Message::NONE);
  }
  #[inline]
  pub fn add_message(&mut self, message: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Envelope::VT_MESSAGE, message);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> EnvelopeBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    EnvelopeBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Envelope<'a>> {
    let o = self.fbb_.end_table(self.start_);
    flatbuffers::WIPOffset::new(o.value())
  }
}

impl core::fmt::Debug for Envelope<'_> {
  fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
    let mut ds = f.debug_struct("Envelope");
      ds.field("version", &self.version());
      ds.field("channel", &self.channel());
      ds.field("message_type", &self.message_type());
      match self.message_type() {
        Message::CreateSessionRequest => {
          if let Some(x) = self.message_as_create_session_request() {
            ds.field("message", &x)
          } else {
            ds.field("message", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        Message::CommandBatch => {
          if let Some(x) = self.message_as_command_batch() {
            ds.field("message", &x)
          } else {
            ds.field("message", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        Message::DestroySessionRequest => {
          if let Some(x) = self.message_as_destroy_session_request() {
            ds.field("message", &x)
          } else {
            ds.field("message", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        Message::ResponseBatch => {
          if let Some(x) = self.message_as_response_batch() {
            ds.field("message", &x)
          } else {
            ds.field("message", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        Message::EventMessage => {
          if let Some(x) = self.message_as_event_message() {
            ds.field("message", &x)
          } else {
            ds.field("message", &"InvalidFlatbuffer: Union discriminant does not match value.")
          }
        },
        _ => {
          let x: Option<()> = None;
          ds.field("message", &x)
        },
      };
      ds.finish()
  }
}
